function showCapabilities(){
 content.innerHTML='<section><h2>Capability catalog</h2><p>Working = implemented workflow. Records = operational records only. Integrated = requires an external provider and workspace eligibility. Planned = unavailable. These are equivalent workflow categories, not a claim of exact product parity.</p><label>Find a capability<input id="capability-search" type="search" placeholder="Search payroll, invoices, tax…"></label></section><div class="capability-grid">'+capabilitySections.map(group=>`<section data-feature-group><h2>${esc(group.name)}</h2><p><a href="${group.reference}" target="_blank" rel="noopener noreferrer">Official product scope reference ↗</a></p>${group.items.map(([name,state,page,note],index)=>`<div class="feature-row" data-feature><span class="badge ${state}">${esc(title(state))}</span><strong>${index+1}. ${esc(name)}</strong><small>${esc(note)}</small>${page&&availablePage(page)?`<button data-go="${page}">Open ${esc(pageLabel(page))}</button>`:''}</div>`).join('')}</section>`).join('')+'</div>';
 goButtons();document.querySelector('#capability-search').oninput=e=>{const query=e.target.value.toLowerCase();content.querySelectorAll('[data-feature]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(query));content.querySelectorAll('[data-feature-group]').forEach(group=>group.hidden=![...group.querySelectorAll('[data-feature]')].some(row=>!row.hidden))};
}

let mobileInstallPrompt=null;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();mobileInstallPrompt=event;const button=document.querySelector('#install-mobile');if(button)button.disabled=false});
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/service-worker.js').catch(()=>{}));
async function showDownloads(){
 document.querySelector('#title').textContent='Mobile app downloads';
 content.innerHTML=`<section><img class="login-brand" src="/assets/oob-logo.png" alt="Olamide Olatayo Bello"><h2>Take your workspace with you</h2><p>Accounting, people, tax organization and business management on your phone. Your account and workspace remain the same.</p><button id="install-mobile" ${mobileInstallPrompt?'':'disabled'}>Install web app</button><p>Android Chrome: open the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>. iPhone/iPad Safari: Share → Add to Home Screen. The install button becomes available when your browser offers installation.</p><p class="notice">Business data requires an internet connection. Offline caching is limited to public brand icons; authenticated responses are not cached.</p></section><section><h2>Android APK preview</h2><div id="apk-download-status">Checking published Android builds…</div><p><a href="/">Sign in</a> · <a href="/register">Create a business account</a></p></section>`;
 document.querySelector('#install-mobile').onclick=async()=>{if(mobileInstallPrompt){await mobileInstallPrompt.prompt();await mobileInstallPrompt.userChoice;mobileInstallPrompt=null;document.querySelector('#install-mobile').disabled=true}};
 try{const build=await api('mobile');document.querySelector('#apk-download-status').innerHTML=build.apk_available?`<a class="download-link" href="${esc(build.apk_url)}">Download Android preview APK</a><p>${esc(build.build_type)}. This is a test build, not a production-signed or Play Store release. Banking OAuth and external links may open your device browser.</p>`:`<p>No published APK is available yet. The web app installation is available above.</p><a href="${esc(build.workflow_url)}" target="_blank" rel="noopener noreferrer">View Android build status ↗</a>`}catch{document.querySelector('#apk-download-status').textContent='Build status is unavailable. Use the web app installation or check GitHub Actions.'}
}
async function showDeployment(){
 const status=await api('platform/status');const readiness=status.state.readiness;const busy=status.jobs.some(j=>['queued','running'].includes(j.state));const ready=!!readiness?.deployment_source_ready;
 const operations=[['verify','Run readiness checks','Check systemd services, timers, nginx and local HTTPS application identity.'],['backup','Back up all workspaces','Create consistent catalog and tenant database snapshots.'],['deploy','Deploy installed source','Run the trusted, root-owned deployment source already installed on this host.'],['commission','Recommission platform','Reapply dependencies, services, database initialization, routing and public verification using the installed source.']];
 content.innerHTML=`<section><header><div><h2>Deployment, installation & commissioning</h2><p>Fixed operations run through a root-owned management broker. No shell commands or paths are accepted from the browser.</p></div><button id="deployment-refresh">Refresh status</button></header>${readiness?`<p>Last checked: ${esc(readiness.checked_at)}</p>${table(Object.entries(readiness.services).map(([service,state])=>({service,state})),['service','state'])}`:'<p class="notice">The management broker has not reported yet. Complete the Ansible deployment and allow up to one minute for its first check.</p>'}<div class="capability-grid">${operations.map(([kind,label,note])=>`<div class="card"><h3>${label}</h3><p>${note}</p><button data-platform-operation="${kind}" ${!ready||busy?'disabled':''}>${label}</button></div>`).join('')}</div><p class="notice">Deploy and recommission may briefly restart the workspace service. New GitHub commits require an operator to pull and deploy them on the server; this GUI deploys the installed trusted source.</p></section><section><h2>Operation history</h2>${status.jobs.length?table(status.jobs,['created','kind','state','summary']):'<p class="empty-state">No management operations have been requested.</p>'}</section>`;
 document.querySelector('#deployment-refresh').onclick=()=>showDeployment().catch(e=>message(e.message));content.querySelectorAll('[data-platform-operation]').forEach(b=>b.onclick=async()=>{try{content.querySelectorAll('[data-platform-operation]').forEach(button=>button.disabled=true);await api('platform/jobs',{kind:b.dataset.platformOperation});message('Operation queued. The management broker processes it automatically.');await showDeployment()}catch(error){message(error.message);await showDeployment()}});
 if(busy)setTimeout(()=>{if(current==='deployment')showDeployment().catch(()=>message('The service may be restarting. Refresh status when it is available.'))},7000);
}

async function showMarketplace(page){
 const [status,products]=await Promise.all([api('market/status'),api('market/products')]);
 if(['commerce_admin','subscription_plans','subscriptions_admin','payment_gateways','store_admin'].includes(page)){await showCommerceAdministration(page,status,products);return}
 const money=(amount,currency)=>formatMoneyMinor(amount,currency);
 const notice=`<p class="notice">${esc(status.environment.toUpperCase())} payments · ${esc(status.notice)}</p>`;
 if(page==='marketplace'){
  const live=products.filter(p=>p.active);
  content.innerHTML='<section><h2>'+esc(status.store.name)+'</h2><p>'+esc(status.store.description)+'</p><p>'+esc(status.store.support_email)+'</p>'+(!status.store.open?'<p class="notice">Store purchases are paused.</p>':'')+notice+'<p>Purchase a one-time service for the current workspace. Payment activates a service record and adds it to the platform fulfillment queue. Human services still require staff delivery.</p><button data-go="market_orders">View orders</button> <button data-go="market_services">Purchased services</button></section><div class="grid">'+live.map(p=>{const gateways=status.gateways.filter(g=>g.configured&&g.currency===p.currency);return `<section class="card"><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><strong>${esc(money(p.amount,p.currency))} ${p.days?'per '+p.days+' day prepaid term':'one time'}</strong>${gateways.map(g=>`<button data-buy="${esc(p.id)}" data-gateway="${g.id}" ${isAdmin()?'':'disabled'}>Pay with ${esc(g.id)}</button>`).join('')}${!gateways.length?'<p>Payment gateway unavailable for this currency.</p>':''}<label>Full-service coupon<input data-coupon-code="${esc(p.id)}" maxlength="80" autocomplete="off"></label><button data-coupon-pay="${esc(p.id)}">Pay with coupon</button></section>`}).join('')+(!live.length?'<section><p>No offers published. The super administrator can add and publish offers in Marketplace administration.</p></section>':'')+'</div>';
  goButtons();content.querySelectorAll('[data-coupon-pay]').forEach(b=>b.onclick=()=>safeRun(async()=>{b.disabled=true;try{const code=Array.from(content.querySelectorAll('[data-coupon-code]')).find(i=>i.dataset.couponCode===b.dataset.couponPay).value;const storage='oob-coupon-request-'+currentUserId+'-'+currentTenantId+'-'+b.dataset.couponPay;let request_key=sessionStorage.getItem(storage);if(!request_key){request_key=crypto.randomUUID();sessionStorage.setItem(storage,request_key)}const order=await api('coupons/redeem',{product_id:b.dataset.couponPay,code,request_key});sessionStorage.removeItem(storage);await show('market_services');message(order.notice||'Coupon service already activated')}finally{b.disabled=false}}));content.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>safeRun(async()=>{b.disabled=true;const storage='oob-purchase-'+currentUserId+'-'+currentTenantId+'-'+b.dataset.buy+'-'+b.dataset.gateway;let request_key=sessionStorage.getItem(storage);if(!request_key){request_key=crypto.randomUUID();sessionStorage.setItem(storage,request_key)}try{const r=await api('market/checkout',{product_id:b.dataset.buy,gateway:b.dataset.gateway,request_key});if(r.url){const url=new URL(r.url);if(url.protocol!=='https:'||!['checkout.stripe.com','checkout.paystack.com'].includes(url.hostname))throw Error('Invalid checkout address');location.assign(url.href)}else{if(['fulfilled','test_fulfilled'].includes(r.state))sessionStorage.removeItem(storage);message('Order already exists: '+r.state);show('market_orders')}}finally{b.disabled=false}}));return;
 }
 if(page==='market_orders'){
  const rows=await api('market/orders');content.innerHTML='<section><h2>Marketplace orders</h2>'+notice+'<p>A checkout redirect does not confirm payment. Verification checks the provider, amount, currency and order reference. Fulfilled means the service record is active; track delivery under Purchased services.</p>'+rows.map(r=>`<div class="card"><h3>${esc(r.name)} · ${esc(money(r.amount,r.currency))}</h3><p>${esc(r.id)} · Workspace ${r.tenant_id} · ${esc(r.gateway)} · ${esc(r.environment)} · ${esc(r.state)}</p><p>${esc(r.error)}</p>${isAdmin()&&!['fulfilled','test_fulfilled','payment_review'].includes(r.state)?`<button data-verify-order="${esc(r.id)}">Verify payment now</button>`:''}</div>`).join('')+(!rows.length?'<p>No orders yet.</p>':'')+'</section>';
  content.querySelectorAll('[data-verify-order]').forEach(b=>b.onclick=()=>safeRun(async()=>{b.disabled=true;try{const r=await api('market/verify',{id:b.dataset.verifyOrder});message('Verified order status: '+r.state);await show('market_orders')}finally{b.disabled=false}}));return;
 }
 if(page==='market_services'){
  if(!taxOnlyAccount){await showCustomerSubscriptions();return}
  const rows=await api('market/services');content.innerHTML='<section><h2>Purchased services & fulfillment</h2>'+notice+rows.map(r=>`<div class="card"><h3>${esc(r.name)}</h3><p>Workspace ${r.tenant_id} · ${esc(r.service_code)} · ${esc(r.environment)} · ${esc(r.status)} · Delivery: ${esc(r.work_state)}</p><p>Order ${esc(r.order_id)}</p>${userRole==='super_admin'?`<label>Delivery state<select data-service-state="${esc(r.order_id)}">${['new','in_progress','completed','suspended'].map(x=>`<option ${x===r.work_state?'selected':''}>${x}</option>`).join('')}</select></label><button data-service-save="${esc(r.order_id)}">Update fulfillment</button>`:''}</div>`).join('')+(!rows.length?'<p>No purchased services yet.</p>':'')+'</section>';
  content.querySelectorAll('[data-service-save]').forEach(b=>b.onclick=()=>safeRun(async()=>{const select=Array.from(content.querySelectorAll('[data-service-state]')).find(s=>s.dataset.serviceState===b.dataset.serviceSave);await api('market/service-action',{order_id:b.dataset.serviceSave,work_state:select.value});message('Fulfillment updated');show('market_services')}));return;
 }
 if(page==='market_admin'){
  content.innerHTML='<section><h2>Marketplace administration</h2>'+commerceNavigation()+notice+table(status.gateways,['id','currency','configured','signing_key_configured','last_signed_event'])+'<p>Gateway credentials are configured in Provider provisioning & keys or through Ansible. Refunds and disputes require reconciliation in the merchant console; suspend the service in Purchased services as needed.</p><button data-go="market_orders">All orders</button> <button data-go="market_services">Fulfillment queue</button></section><section><h2>Offers</h2>'+products.map(p=>`<p>${esc(p.name)} · ${esc(money(p.amount,p.currency))} · ${p.active?'Published':'Archived'} <button data-edit-offer="${esc(p.id)}">Edit</button> <button data-archive-offer="${esc(p.id)}">Archive</button></p>`).join('')+'<p>For tax-only access, publish a tax-year offer with service code <code>tax_preparation_2026</code> (replace the year as needed). Set your own price. Only verified live payments unlock that year. Describe this as preparation intake; this interview does not provide IRS filing.</p><h3>Generate editable tax service offers</h3><form id="seed-products-form"><label>Preparation price (USD)<input name="preparation_price" type="number" min="0.50" step="0.01" value="49.00" required></label><label>Amendment price (USD)<input name="amendment_price" type="number" min="0.50" step="0.01" value="79.00" required></label><label><input name="publish" type="checkbox" checked> Publish new offers</label><label><input name="overwrite" type="checkbox"> Replace existing starter offer prices and content</label><button>Generate six-year products & prices</button></form><p>Editable starter prices for preparation access only. No IRS filing or maximum-refund guarantee is included.</p><h3 id="offer-editor-title">Create offer</h3><form id="offer-form"><input name="id" type="hidden"><label>Name<input name="name" required maxlength="120"></label><label>Description<textarea name="description" maxlength="2000"></textarea></label><label>Service code<input name="service_code" required pattern="[a-z][a-z0-9_]{1,59}" placeholder="tax_preparation_2026"></label><label>Price in the currency’s minor units<input name="amount" type="number" min="50" max="100000000" required step="1"></label><label>Currency<select name="currency">'+(intlCatalog?.currencies||[{id:'USD'},{id:'NGN'}]).map(c=>'<option '+(c.id==='USD'?'selected':'')+'>'+c.id+'</option>').join('')+'</select></label><label><input name="active" type="checkbox"> Publish this offer</label><button>Save offer</button> <button type="reset">New offer</button></form></section>';
  goButtons();content.querySelector('#seed-products-form').onsubmit=e=>{e.preventDefault();safeRun(async()=>{const form=e.target,data=Object.fromEntries(new FormData(form));data.publish=form.elements.publish.checked;data.overwrite=form.elements.overwrite.checked;const result=await api('market/seed-products',data);await show('market_admin');message('Starter offers: '+result.created+' created, '+result.updated+' updated, '+result.preserved+' preserved')})};const form=content.querySelector('#offer-form');form.onsubmit=e=>{e.preventDefault();safeRun(async()=>{const d=Object.fromEntries(new FormData(form));d.amount=Number(d.amount);d.active=form.elements.active.checked;await api('market/products',d);message('Offer saved');show('market_admin')})};
  content.querySelectorAll('[data-edit-offer]').forEach(b=>b.onclick=()=>{const p=products.find(p=>p.id===b.dataset.editOffer);for(const k of ['id','name','description','service_code','amount','currency'])form.elements[k].value=p[k];form.elements.active.checked=!!p.active;form.scrollIntoView({behavior:'smooth'})});
  content.querySelectorAll('[data-archive-offer]').forEach(b=>b.onclick=()=>safeRun(async()=>{await api('market/products',{id:b.dataset.archiveOffer,action:'archive'});show('market_admin')}));
 }
}

const commercePages=['commerce_admin','market_admin','subscription_plans','subscriptions_admin','market_orders','market_services','payment_gateways','store_admin','coupons','marketplace'];
function commerceNavigation(){return '<div class="quick-links">'+commercePages.filter(availablePage).map(p=>`<button data-go="${p}">${esc(pageLabel(p))}</button>`).join('')+'</div>'}
function subscriptionCards(rows,admin=false){return rows.map(r=>`<div class="card"><h3>${esc(r.name)}</h3><p>${esc(r.state)} · ${esc(r.environment)} · Ends ${esc(new Date(r.ends*1000).toLocaleString())}</p>${admin?`<p>Workspace ${r.tenant_id} · User ${r.owner}</p>`:''}<small>${esc(r.order_id)}</small>${r.state==='active'?`<button data-cancel-sub="${esc(r.order_id)}">Cancel access now</button>`:''}<button data-go="marketplace">Purchase another term</button></div>`).join('')||'<p>No subscriptions yet.</p>'}
function wireSubscriptionActions(){goButtons();content.querySelectorAll('[data-cancel-sub]').forEach(b=>b.onclick=()=>{if(!confirm('Cancel this prepaid term immediately? Access will stop. This does not issue a refund.'))return;safeRun(async()=>{b.disabled=true;try{await api('market/subscription-action',{order_id:b.dataset.cancelSub,action:'cancel'});await show(current);message('Subscription cancelled; no refund issued')}finally{b.disabled=false}})})}
async function showCustomerSubscriptions(){
 const [rows,subs]=await Promise.all([api('market/services'),api('market/subscriptions')]);
 content.innerHTML='<section><h2>Purchased services & fulfillment</h2><p>Prepaid terms expire at the displayed date. Renew by purchasing another term; no automatic charges occur.</p>'+commerceNavigation()+'</section><section><h2>Subscriptions</h2>'+subscriptionCards(subs,userRole==='super_admin')+'</section><section><h2>Service fulfillment</h2>'+rows.map(r=>`<div class="card"><h3>${esc(r.name)}</h3><p>Workspace ${r.tenant_id} · ${esc(r.service_code)} · ${esc(r.environment)} · ${esc(r.status)} · Delivery: ${esc(r.work_state)}</p><small>${esc(r.order_id)}</small>${userRole==='super_admin'?`<label>Delivery state<select data-service-state="${esc(r.order_id)}">${['new','in_progress','completed','suspended'].map(x=>`<option ${x===r.work_state?'selected':''}>${x}</option>`).join('')}</select></label><button data-service-save="${esc(r.order_id)}">Update fulfillment</button>`:''}</div>`).join('')+'</section>';
 wireSubscriptionActions();content.querySelectorAll('[data-service-save]').forEach(b=>b.onclick=()=>safeRun(async()=>{const select=[...content.querySelectorAll('[data-service-state]')].find(s=>s.dataset.serviceState===b.dataset.serviceSave);await api('market/service-action',{order_id:b.dataset.serviceSave,work_state:select.value});await show('market_services');message('Fulfillment updated')}));
}
async function showCommerceAdministration(page,status,products){
 const header=`<section><h2>${esc(pageLabel(page))}</h2>${commerceNavigation()}<p>${esc(status.environment.toUpperCase())} payments · Prepaid plans require a new purchase for renewal.</p></section>`;
 if(page==='store_admin'){
  const s=status.store;
  content.innerHTML=header+`<section><h2>Store identity & availability</h2><form id="store-settings"><label>Store name<input name="name" maxlength="120" required value="${esc(s.name)}"></label><label>Description<textarea name="description" maxlength="2000">${esc(s.description)}</textarea></label><label>Support email<input name="support_email" type="email" maxlength="254" value="${esc(s.support_email)}"></label><label><input name="open" type="checkbox" ${s.open?'checked':''}> Accept new purchases and coupon redemptions</label><p>Pausing purchases preserves existing orders, payment verification and purchased services.</p><button>Save store settings</button><button type="button" data-go="marketplace">Preview store</button></form></section>`;
  goButtons();content.querySelector('#store-settings').onsubmit=e=>{e.preventDefault();safeRun(async()=>{const f=e.target;await api('market/store',{...Object.fromEntries(new FormData(f)),open:f.elements.open.checked});await show(page);message('Store settings saved')})};return;
 }
 if(page==='payment_gateways'){
  content.innerHTML=header+'<section><h2>Gateway readiness</h2>'+table(status.gateways,['id','currency','configured','signing_key_configured','last_signed_event'])+'<p>Keys are encrypted and never displayed here. Confirm your current password in Provider provisioning & keys to save credentials, test merchant connections, change test/live settings or provision a Stripe webhook.</p><button data-go="provider_keys">Configure and test payment gateways</button><button data-go="market_orders">Reconcile orders</button><p>Refunds and disputes must be handled in your merchant dashboard; suspend associated services here when appropriate.</p><a href="https://dashboard.stripe.com/" target="_blank" rel="noopener noreferrer">Stripe dashboard ↗</a> · <a href="https://dashboard.paystack.com/" target="_blank" rel="noopener noreferrer">Paystack dashboard ↗</a></section>';goButtons();return;
 }
 if(page==='subscriptions_admin'){
  const rows=await api('market/subscriptions');content.innerHTML=header+'<section><h2>All prepaid subscriptions</h2><label>Search subscriptions<input id="subscription-search" type="search" placeholder="Name, workspace, user or state"></label><button id="subscription-export">Export CSV</button><div id="subscription-list">'+subscriptionCards(rows,true)+'</div></section>';
  const render=q=>{content.querySelector('#subscription-list').innerHTML=subscriptionCards(rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q)),true);wireSubscriptionActions()};wireSubscriptionActions();content.querySelector('#subscription-search').oninput=e=>render(e.target.value.toLowerCase());content.querySelector('#subscription-export').onclick=()=>downloadCsv('subscriptions.csv',rows,['order_id','name','tenant_id','owner','environment','state','ends']);return;
 }
 if(page==='subscription_plans'){
  const plans=await api('market/plans');
  content.innerHTML=header+'<section><h2>Prepaid subscription plans</h2><p>Each verified payment or accepted coupon starts one fixed term. Editing a plan affects future orders; existing orders retain their purchased term. Plans create service fulfillment records and do not automatically enable unrelated modules.</p>'+plans.map(p=>`<div class="card"><h3>${esc(p.name)}</h3><p>${esc(formatMoneyMinor(p.amount,p.currency))} / ${p.days} days · ${p.active?'Published':'Archived'}</p><button data-edit-plan="${esc(p.id)}">Edit plan</button><button data-archive-plan="${esc(p.id)}">Archive plan</button></div>`).join('')+`<h3>Plan editor</h3><form id="plan-form"><input name="id" type="hidden"><label>Name<input name="name" required maxlength="120"></label><label>Description<textarea name="description" maxlength="2000"></textarea></label><label>Service code<input name="service_code" required pattern="[a-z][a-z0-9_]{1,59}" placeholder="bookkeeping_support"></label><label>Price in minor units<input name="amount" type="number" required min="50" max="100000000" step="1"></label><label>Currency<select name="currency"><option>USD</option><option>NGN</option></select></label><label>Term in days<input name="days" type="number" min="1" max="366" value="30" step="1" required></label><label><input name="active" type="checkbox"> Publish plan</label><button>Save plan</button><button type="reset">New plan</button></form></section>`;
  goButtons();const f=content.querySelector('#plan-form');f.onsubmit=e=>{e.preventDefault();safeRun(async()=>{const data=Object.fromEntries(new FormData(f));data.amount=Number(data.amount);data.days=Number(data.days);data.active=f.elements.active.checked;await api('market/plans',data);await show(page);message('Plan saved')})};content.querySelectorAll('[data-edit-plan]').forEach(b=>b.onclick=()=>{const p=plans.find(p=>p.id===b.dataset.editPlan);for(const k of ['id','name','description','service_code','amount','currency','days'])f.elements[k].value=p[k];f.elements.active.checked=!!p.active;f.scrollIntoView({behavior:'smooth'})});content.querySelectorAll('[data-archive-plan]').forEach(b=>b.onclick=()=>safeRun(async()=>{await api('market/products',{id:b.dataset.archivePlan,action:'archive'});await show(page)}));return;
 }
 const [orders,services,subs]=await Promise.all([api('market/orders'),api('market/services'),api('market/subscriptions')]);
 const totals={};orders.filter(o=>o.environment==='live'&&o.state==='fulfilled').forEach(o=>totals[o.currency]=(totals[o.currency]||0)+o.amount);
 content.innerHTML=header+'<div class="grid">'+[['Published offers',products.filter(p=>p.active).length,'market_admin'],['Orders (latest 500)',orders.length,'market_orders'],['Services (latest 500)',services.length,'market_services'],['Active prepaid terms (latest 500)',subs.filter(s=>s.state==='active').length,'subscriptions_admin']].map(([name,value,page])=>`<button class="card" data-go="${page}">${esc(name)}<strong>${value}</strong></button>`).join('')+'</div><section><h2>Verified live order totals (latest 500 orders)</h2>'+Object.entries(totals).map(([currency,total])=>`<p>${esc(formatMoneyMinor(total,currency))}</p>`).join('')+'<p>Gross verified order amounts only; exclude fees, refunds, disputes, test orders and coupons. Reconcile merchant statements for accounting.</p><h2>Store status</h2><p>'+esc(status.store.name)+' · '+(status.store.open?'Purchases open':'Purchases paused')+'</p></section>';goButtons();
}

let watchdogRefreshTimer;
async function showWatchdog(){
 clearTimeout(watchdogRefreshTimer);
 const r=await api('platform/watchdog');
 const stamp=t=>t?new Date(t*1000).toLocaleString():'No report';
 const latest=r.latest;
 content.innerHTML=`<section><header><div><h2>Watchdog events & reports</h2><p>Automatic checks every minute. Two consecutive failures trigger a web restart, with a 15-minute cooldown.</p></div><button id="watchdog-refresh">Refresh</button></header><p role="status">${!r.installed?'Watchdog reports are not installed yet.':r.stale?'Reports are stale. Check the watchdog timer on the server.':'Watchdog is reporting.'}</p>${latest?`<p>Latest: ${esc(latest.action)} · ${esc(stamp(latest.checked_at))} · consecutive failures: ${esc(latest.failures)}</p>${table(Object.entries(latest.checks).map(([check,ok])=>({check,result:ok?'Passed':'Failed'})),['check','result'])}`:''}<h3>Last 24 hours</h3>${table(Object.entries(r.summary).map(([action,count])=>({action,count})),['action','count'])}<p>Counts represent recorded events, including restart requests and outcomes. History retains 90 days; the latest 200 events appear below.</p><button id="watchdog-export">Download displayed report</button></section><section><h2>Event history</h2>${r.events.length?table(r.events.map(e=>({id:e.id,time:stamp(e.checked_at),action:e.action,failures:e.failures,service:e.service,checks:Object.entries(e.checks).map(([k,v])=>k+': '+(v?'passed':'failed')).join('; ')})),['id','time','action','failures','service','checks']):'<p>No watchdog events recorded.</p>'}</section>`;
 document.querySelector('#watchdog-refresh').onclick=()=>showWatchdog().catch(e=>message(e.message));
 document.querySelector('#watchdog-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='watchdog-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 watchdogRefreshTimer=setTimeout(()=>{if(current==='watchdog')showWatchdog().catch(e=>message(e.message))},60000);
}
